\title{Гибридный метод субградиента и метода имитации отжига для гемивариационных неравенств}

\author{Piotr~Bartman-Szwarc\inst{1,2}\orcidID{0000-0003-0265-6428} \and
Adil~M.~Bagirov\inst{3}\orcidID{0000-0003-2075-1699} \and Anna~Ochal\inst{1}\orcidID{0000-0003-4385-2302}}
